def minimize_maximum_liquid(R, G, B, M, r, g, b):
    for _ in range(M):
        max_r = max(r)
        max_g = max(g)
        max_b = max(b)

        if max_r >= max_g and max_r >= max_b:
            r[r.index(max_r)] = max_r // 2
        elif max_g >= max_r and max_g >= max_b:
            g[g.index(max_g)] = max_g // 2
        else:
            b[b.index(max_b)] = max_b // 2

